import Rectangle from '@/helpers/Rectangle'
import Frame from '@/renderer/Frame'
import Overlay from '@/renderer/Overlay'
import { addButtonRect, addButtonText } from '@/renderer/OverlayButtons'
import Units from '@/helpers/Units'
import Queue from '@/render/Queue'
import QueueItemsBuilder from '@/builders/QueueItemsBuilder'
import HoverProgress from '@/types/HoverProgress'
import { AnimationTiming } from '@/static/constants/Index'
import { FocusOrder, Icon } from '@/static/Enums'

const WIDTH = 28

const HEIGHT = 24

const PADDING = 8

const FONT_SIZE = 20

export default class MenuButton extends Overlay {
    static readonly rowHeight = HEIGHT + PADDING * 2

    onClick?: () => void

    bounds?: DOMRect

    private size?: { width: number, height: number }

    private hover = new HoverProgress()

    private isDirty = true

    resize(width: number, height: number, top: number) {
        this.size = { width, height }
        this.bounds = new DOMRect(width - PADDING - WIDTH, Math.max((top - HEIGHT) / 2, PADDING), WIDTH, HEIGHT)
        this.isDirty = true
    }

    update({ queue, mouse, now, theme, isInstant }: Frame) {
        if (!this.bounds || !this.size || this.size.width <= 0 || this.size.height <= 0) {
            this.clear(queue)

            return false
        }

        const bounds = this.bounds

        const isHoverChanged = this.hover.step(
            Rectangle.contains(bounds, mouse),
            now,
            AnimationTiming.button,
            isInstant
        )

        if (!this.isDirty && !isHoverChanged)
            return this.hover.isAnimating

        const units = Units.fromSize(this.size.width, this.size.height)

        this.show(queue, QueueItemsBuilder.build((items: QueueItemsBuilder) => {
            addButtonRect(items, units, {
                rect: bounds,
                radius: 4,
                hover: this.hover.value,
                focusOrder: FocusOrder.Menu,
                onClick: () => this.onClick?.()
            }, theme)
            addButtonText(items, units, { rect: bounds, text: Icon.ThreeDots, size: FONT_SIZE }, theme)
        }))

        this.isDirty = false

        return this.hover.isAnimating
    }

    clear(queue: Queue) {
        this.isDirty = true

        this.remove(queue)
    }
}